<template>

  <KButton
    v-if="canDownload"
    ref="button"
    hasDropdown
    :primary="$attrs.primary"
  >
    <span>{{ $tr('downloadContent') }}</span>
    <template #menu>
      <KDropdownMenu
        :options="fileOptions"
        maxWidth="none"
        @select="download"
      />
    </template>
  </KButton>

</template>


<script>

  import { validateObject } from 'kolibri/utils/objectSpecs';
  import { getRenderableFiles } from './internal/ContentViewer/utils';
  import { getFilePresetString } from './internal/filePresetStrings';

  export default {
    name: 'DownloadButton',
    props: {
      files: {
        type: Array,
        default: () => [],
        validator: function (files) {
          return files.every(file =>
            validateObject(file, {
              checksum: { type: String, required: true },
              extension: { type: String, required: true },
              preset: { type: String, required: true },
              lang: {
                type: Object,
                required: false,
                default: () => ({}),
                spec: {
                  lang_name: {
                    type: String,
                    required: true,
                  },
                },
              },
              // None for a file that isn't on the device
              storage_url: { type: String, default: null },
            }),
          );
        },
      },
      nodeTitle: {
        type: String,
        default: '',
      },
    },
    computed: {
      downloadableFiles() {
        return getRenderableFiles(this.files).filter(file => file.preset !== 'exercise');
      },
      canDownload() {
        return this.downloadableFiles.length > 0;
      },
      fileOptions() {
        const options = this.files.map(file => {
          const label = getFilePresetString(file);
          const fileId =
            file.preset === 'video_subtitle' && file?.lang.lang_name
              ? file?.lang.lang_name
              : file.checksum.slice(0, 6);
          return {
            label,
            url: file.storage_url,
            fileName: this.$tr('downloadFilename', {
              resourceTitle: this.nodeTitle.length ? this.nodeTitle : file.checksum,
              fileExtension: file.extension,
              fileId,
            }),
          };
        });
        return options;
      },
    },
    methods: {
      download(file) {
        const a = document.createElement('a');
        a.download = file.fileName;
        a.href = file.url;
        document.body.appendChild(a);
        a.click();
        a.remove();
      },
    },
    $trs: {
      downloadContent: {
        message: 'Save to device',
        context:
          "The 'SAVE TO DEVICE' button allows learners to download learning resources, like a PDF document for example, to their own device.",
      },
      downloadFilename: {
        message: '{ resourceTitle } ({ fileId }).{ fileExtension }',
        context: 'DO NOT TRANSLATE\nCopy the source string.\n',
      },
    },
  };

</script>


<style lang="scss" scoped></style>
